import { siteData } from "@/components/data/siteData";

// Generated by src/app/opengraph-image.js. Listed explicitly because a page
// that sets its own `openGraph` replaces the parent's, file-based image included.
const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteData.name} – ${siteData.jobTitle} at ${siteData.company}`,
};

// Next.js merges metadata shallowly, so every page builds its complete
// canonical, Open Graph and Twitter set here. Twitter falls back to the
// Open Graph title, description and image.
export function pageMetadata({ title, description, path }) {
  return {
    ...(title && { title }),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "profile",
      firstName: siteData.givenName,
      lastName: siteData.familyName,
      username: siteData.githubUsername,
      siteName: siteData.name,
      locale: "en_US",
      url: path,
      title: title ? `${title} | ${siteData.name}` : siteData.title,
      description,
      images: [ogImage],
    },
    twitter: { card: "summary_large_image" },
  };
}
